-- Immutable slim card snapshot generated from the sealed owner-approved release.
-- This prevents later live Product Truth/media edits from silently changing the approved preview.

create table if not exists public.feya_storefront_product_card_snapshots_v1 (
  canonical_product_id uuid primary key,
  seo_page_id uuid not null unique,
  draft_id uuid not null unique,
  content_sha256 text not null check (content_sha256 ~ '^[0-9a-f]{64}$'),
  source_release_ref text not null check (source_release_ref='feya-review-207-20260924'),
  product_slug text not null unique,
  card_title text not null,
  h1 text not null,
  seo_title text not null,
  meta_description text not null,
  product_type text,
  material text,
  color text,
  currency text,
  primary_image_url text not null,
  primary_image_alt text,
  secondary_image_url text,
  hover_image_url text,
  video_url text,
  has_video boolean,
  media_count integer,
  min_price numeric,
  max_price numeric,
  card_display_price_amount numeric not null,
  category_label text,
  world_label text,
  canonical_color_label text,
  color_options jsonb,
  created_at timestamptz not null default now()
);

comment on table public.feya_storefront_product_card_snapshots_v1 is
  'Immutable slim card presentation for the 207 visible products in feya-review-207-20260924.';

revoke all on public.feya_storefront_product_card_snapshots_v1 from public, anon, authenticated;
grant select on public.feya_storefront_product_card_snapshots_v1 to service_role;

insert into public.feya_storefront_product_card_snapshots_v1 (
  canonical_product_id,seo_page_id,draft_id,content_sha256,source_release_ref,
  product_slug,card_title,h1,seo_title,meta_description,product_type,material,color,currency,
  primary_image_url,primary_image_alt,secondary_image_url,hover_image_url,video_url,has_video,media_count,
  min_price,max_price,card_display_price_amount,category_label,world_label,canonical_color_label,color_options
)
